# ======================================================================
#   ASTRONOMY (as in HaslaLab's other observation desks)
# ======================================================================
def norm360(a):
    return a % 360.0


def jd_ut(y, m, d, h):
    if m <= 2:
        y -= 1
        m += 12
    A = y // 100
    B = 2 - A + A // 4
    return math.floor(365.25 * (y + 4716)) + math.floor(30.6001 * (m + 1)) + d + B - 1524.5 + h / 24


def gmst_deg(J):
    T_ = (J - 2451545) / 36525
    return norm360(280.46061837 + 360.98564736629 * (J - 2451545) + 0.000387933 * T_ * T_)


def vec(ra, dec):
    return [math.cos(dec * DEG) * math.cos(ra * DEG), math.cos(dec * DEG) * math.sin(ra * DEG), math.sin(dec * DEG)]


def mv(M, v):
    return [M[i][0] * v[0] + M[i][1] * v[1] + M[i][2] * v[2] for i in range(3)]


def mvT(M, v):
    return [M[0][i] * v[0] + M[1][i] * v[1] + M[2][i] * v[2] for i in range(3)]


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]


def precession(J):
    T_ = (J - 2451545) / 36525
    a = DEG / 3600
    z = (2306.2181 * T_ + 1.09468 * T_ * T_) * a
    ze = (2306.2181 * T_ + 0.30188 * T_ * T_) * a
    th = (2004.3109 * T_ - 0.42665 * T_ * T_) * a
    cz, sz, ce, se, ct, st = math.cos(z), math.sin(z), math.cos(ze), math.sin(ze), math.cos(th), math.sin(th)
    return [[cz * ct * ce - sz * se, -cz * ct * se - sz * ce, -cz * st], [sz * ct * ce + cz * se, -sz * ct * se + cz * ce, -sz * st], [st * ce, -st * se, ct]]


def hor_matrix(J):
    P = precession(J)
    th = norm360(gmst_deg(J) + SITE["lon"]) * DEG
    p = SITE["lat"] * DEG
    c, s = math.cos(th), math.sin(th)
    R = [[-s, c, 0], [-math.sin(p) * c, -math.sin(p) * s, math.cos(p)], [math.cos(p) * c, math.cos(p) * s, math.sin(p)]]
    return [[sum(R[i][k] * P[k][j] for k in range(3)) for j in range(3)] for i in range(3)]


def altaz(h):
    return math.asin(max(-1.0, min(1.0, h[2]))) / DEG, norm360(math.atan2(h[0], h[1]) / DEG)


def hvec(alt, az):
    return [math.sin(az * DEG) * math.cos(alt * DEG), math.cos(az * DEG) * math.cos(alt * DEG), math.sin(alt * DEG)]


def refr(a):
    return 1.02 / math.tan((a + 10.3 / (a + 5.11)) * DEG) / 60 if a > -2 else 0.0


def airmass(a):
    a = max(0.5, a)
    return 1 / (math.sin(a * DEG) + 0.50572 * (a + 6.07995) ** -1.6364)


def _stars():
    out = []
    for ra, de, v, bv in struct.iter_unpack("<HhhB", base64.b64decode(STARDATA)):
        out.append([vec(ra / 180, de / 360), v / 100, bv / 80 - 0.5])
    return out


STARS = _stars()


def bv_rgb(bv):
    t = max(-0.4, min(2.0, bv))
    if t < 0.4:
        r, g, b = 0.72 + 0.7 * (t + 0.4), 0.8 + 0.4 * (t + 0.4), 1.0
    else:
        r, g, b = 1.0, 1.05 - 0.28 * (t - 0.4), 1 - 0.45 * (t - 0.4)
    return min(1, r), min(1, g), max(0.35, min(1, b))


def hexc(r, g, b):
    return "#%02x%02x%02x" % (int(max(0, min(255, r))), int(max(0, min(255, g))), int(max(0, min(255, b))))


def skyline(az):
    az = norm360(az)
    d = ((az - 300 + 540) % 360) - 180
    return (2.2 + 0.9 * math.sin(az * 0.035 + 1.2) + 0.5 * math.sin(az * 0.11 + 0.3) + 0.25 * math.sin(az * 0.47 + 2.0) + 0.12 * math.sin(az * 1.9)
            + 1.6 * math.exp(-((d / 18) ** 2)))


def table_pos(n):
    r, c = (n - 1) // 8, (n - 1) % 8
    return c * 3 - 10.5, -r * 3


def lamp_from(n):
    """Azimuth, altitude, distance of the lamp, and the altitude of the mast's foot, seen from table n."""
    x, y = table_pos(n)
    dx, dy = LAMP[0] - x, LAMP[1] - y
    d = math.hypot(dx, dy)
    return {"az": norm360(math.atan2(dx, dy) / DEG), "alt": math.atan2(LAMP[2], d) / DEG, "dist": math.hypot(d, LAMP[2]), "ground": math.atan2(-1.2, d) / DEG}


def focus_of(d):
    """Draw-tube position (mm past the focus for infinity) that focuses an object d metres away."""
    return 0.0 if d == float("inf") else GS_F * GS_F / (d - GS_F) * 1000


