class App:
    def __init__(self, root):
        self.root = root
        root.title(T("IOAA 2024 관측 O1 — 성도 문제와 갈릴레오스코프 · HaslaLab", "IOAA 2024 observation O1 — star charts and the Galileoscope · HaslaLab"))
        root.configure(bg="#1c2027")
        root.geometry("1560x940")
        self.data = self.load()
        if not 1 <= int(self.data.get("table", 0) or 0) <= 40:
            self.data["table"] = random.randint(1, 40)
            self.store()
        self.task = TASKS[0]
        self.sheet = "f1"
        self.tool = "pen"
        self.col = "#c62828"
        self.drag = None
        self.sdrag = None
        self.undo = []
        self.imgs = {}
        self.calc = Calc()
        self.tube = {"az": 0.0, "alt": 0.0, "foc": 17.0}
        self.t0 = time.time()
        self.end = 0
        left = tk.Frame(root, bg="#22262d", width=400)
        left.pack(side="left", fill="y", padx=(10, 5), pady=10)
        left.pack_propagate(False)
        right = tk.Frame(root, bg="#22262d", width=320)
        right.pack(side="right", fill="y", padx=(5, 10), pady=10)
        right.pack_propagate(False)
        mid = tk.Frame(root, bg="#1c2027")
        mid.pack(side="left", fill="both", expand=True, pady=10)
        tb = tk.Frame(left, bg="#22262d")
        tb.pack(fill="x", padx=8, pady=8)
        self.tbtn = {}
        for t in TASKS:
            b = tk.Button(tb, text=t["id"], command=lambda t=t: self.set_task(t), bg="#2b2f36", fg="#e8eef2", relief="flat", font=("Segoe UI", 10, "bold"), padx=10)
            b.pack(side="left", padx=2)
            self.tbtn[t["id"]] = b
        self.qtext = tk.Text(left, wrap="word", bg="#12161b", fg="#d6dde2", relief="flat", font=("Malgun Gothic", 10), padx=10, pady=8)
        self.qtext.pack(fill="both", expand=True, padx=8, pady=(0, 8))
        self.qtext.tag_configure("h", foreground="#f2c14e", font=("Malgun Gothic", 11, "bold"))
        self.sbar = tk.Frame(mid, bg="#1c2027")
        self.sbar.pack(fill="x")
        self.bar = tk.Frame(mid, bg="#1c2027")
        self.bar.pack(fill="x", pady=3)
        self.toolbtn = {}
        for k, lab in TOOLS:
            b = tk.Button(self.bar, text=lab, width=3 if len(lab) < 3 else 5, command=lambda k=k: self.set_tool(k), bg="#2b2f36", fg="#e8eef2", relief="flat")
            b.pack(side="left", padx=1)
            self.toolbtn[k] = b
        for c in ("#111111", "#c62828", "#1f4fd1"):
            tk.Button(self.bar, bg=c, activebackground=c, width=2, relief="flat", command=lambda c=c: setattr(self, "col", c)).pack(side="left", padx=1)
        tk.Button(self.bar, text="↶", command=self.do_undo, bg="#2b2f36", fg="#e8eef2", relief="flat").pack(side="left", padx=4)
        tk.Button(self.bar, text=T("모두 지우기", "Clear"), command=self.clear, bg="#2b2f36", fg="#e8eef2", relief="flat").pack(side="left")
        self.cv = tk.Canvas(mid, bg="#6b6257", highlightthickness=0)
        self.cv.pack(fill="both", expand=True)
        self.form = tk.Frame(mid, bg="#12161b")
        self.form.pack(fill="x", pady=(4, 0))
        self.cv.bind("<Configure>", lambda e: self.redraw())
        self.cv.bind("<ButtonPress-1>", self.down)
        self.cv.bind("<B1-Motion>", self.move)
        self.cv.bind("<ButtonRelease-1>", self.up)
        self.cv.bind("<MouseWheel>", lambda e: self.wheel(1 if e.delta > 0 else -1))
        self.cv.bind("<Button-4>", lambda e: self.wheel(1))
        self.cv.bind("<Button-5>", lambda e: self.wheel(-1))
        root.bind("<Control-z>", lambda e: self.do_undo())
        for k, d in (("Left", (6, 0)), ("Right", (-6, 0)), ("Up", (0, 6)), ("Down", (0, -6))):
            root.bind("<%s>" % k, lambda e, d=d: self.key_nudge(e, d))
        # calculator
        tk.Label(right, text=T("공학용 계산기", "Scientific calculator"), bg="#22262d", fg="#f2c14e", font=("Segoe UI", 11, "bold")).pack(anchor="w", padx=10, pady=(10, 2))
        self.cres = tk.Label(right, text="0", bg="#c9d4c0", fg="#111", font=("Consolas", 15, "bold"), anchor="e", padx=8, pady=6)
        self.cres.pack(fill="x", padx=10)
        self.chist = tk.Label(right, text="", bg="#22262d", fg="#9aa3ab", font=("Consolas", 9), anchor="w")
        self.chist.pack(fill="x", padx=10)
        ce = tk.Entry(right, bg="#0f1216", fg="#e8eef2", insertbackground="#e8eef2", font=("Consolas", 12), relief="flat")
        ce.pack(fill="x", padx=10, pady=3)
        ce.bind("<Return>", lambda e: self.calc_run(ce))
        row = tk.Frame(right, bg="#22262d")
        row.pack(fill="x", padx=10)
        self.degb = tk.Button(row, text="DEG", command=self.toggle_deg, bg="#2b2f36", fg="#e8eef2", relief="flat")
        self.degb.pack(side="left")
        tk.Label(row, text="sin cos tan asin acos atan sqrt ln log exp ^ pi Ans", bg="#22262d", fg="#9aa3ab", font=("Consolas", 8)).pack(side="left", padx=4)
        tk.Label(right, text=T("요약 답안지", "Summary answer sheet"), bg="#22262d", fg="#f2c14e", font=("Segoe UI", 11, "bold")).pack(anchor="w", padx=10, pady=(12, 2))
        self.ans = tk.Frame(right, bg="#22262d")
        self.ans.pack(fill="x", padx=10)
        tk.Button(right, text=T("공식 해답 보기", "Show the official solution"), command=self.show_sol, bg="#2b2f36", fg="#e8eef2", relief="flat").pack(fill="x", padx=10, pady=8)
        self.sol = tk.Label(right, text="", wraplength=290, justify="left", bg="#22262d", fg="#c3cbd2", font=("Malgun Gothic", 9))
        self.sol.pack(fill="x", padx=10)
        self.set_task(TASKS[0])
        self.tick()

    # ---- storage
    def load(self):
        try:
            with open(SAVE, encoding="utf-8") as f:
                d = json.load(f)
        except (OSError, ValueError):
            d = {}
        for k in ("marks", "answers"):
            d.setdefault(k, {})
        return d

    def store(self):
        try:
            with open(SAVE, "w", encoding="utf-8") as f:
                json.dump(self.data, f, ensure_ascii=False)
        except OSError:
            pass

    def marks(self):
        return self.data["marks"].setdefault(self.sheet, [])

    def J(self):
        return jd_ut(DAY[0], DAY[1], DAY[2], START - SITE["tz"]) + (time.time() - self.t0) / 86400

    def tick(self):
        if self.sheet == "scope" and not self.sdrag:
            self.redraw()
            if self.end:
                s = max(0, int(self.end - time.time()))
                self.tmr.configure(text=(T("남은 시간 ", "Time left ") + "%d:%02d" % (s // 60, s % 60)) if s else T("시간이 끝났습니다", "Time is up"), fg="#f3d58a" if s > 60 else "#ff8a70")
        self.root.after(400, self.tick)

    # ---- panels
    def set_task(self, t):
        self.task = t
        for k, b in self.tbtn.items():
            b.configure(bg="#f2c14e" if k == t["id"] else "#2b2f36", fg="#1c2027" if k == t["id"] else "#e8eef2")
        q = self.qtext
        q.configure(state="normal")
        q.delete("1.0", "end")
        q.insert("end", "(%s) %s  [%d %s]\n\n" % (t["id"], t["name"], t["marks"], T("점", "marks")), "h")
        q.insert("end", t["text"])
        q.configure(state="disabled")
        for w in self.sbar.winfo_children():
            w.destroy()
        for s in t["sheets"]:
            tk.Button(self.sbar, text=SHEETS[s]["name"], command=lambda s=s: self.set_sheet(s), bg="#2b2f36", fg="#e8eef2", relief="flat").pack(side="left", padx=2)
        for w in self.ans.winfo_children():
            w.destroy()
        A = self.data["answers"]
        for f in t["fields"]:
            k = t["id"] + "." + f
            r = tk.Frame(self.ans, bg="#22262d")
            r.pack(fill="x", pady=1)
            tk.Label(r, text=f, bg="#22262d", fg="#c3cbd2", width=18, anchor="w").pack(side="left")
            v = tk.StringVar(value=A.get(k, ""))
            v.trace_add("write", lambda *a, k=k, v=v: (A.__setitem__(k, v.get()), self.store()))
            tk.Entry(r, textvariable=v, bg="#14171c", fg="#e8eef2", insertbackground="#e8eef2", relief="flat", width=14).pack(side="right")
        self.sol.configure(text="")
        self.set_sheet(t["sheets"][0])

    def show_sol(self):
        if messagebox.askyesno("IOAA 2024", T("해답을 볼까요? 시험처럼 풀어 보려면 먼저 끝까지 풀어 보세요.", "Show the solution? To work it like the examination, finish first.")):
            self.sol.configure(text=self.task["key"] + self.grade())

    def ans_of(self, i):
        return self.data["answers"].get(self.task["id"] + "." + self.task["fields"][i], "").strip()

    def grade(self):
        t, out = self.task["id"], []
        ok = lambda c, mid=False: " ✓" if c else (" △" if mid else " ✗")
        if t == "1" and self.ans_of(0):
            out.append(self.ans_of(0) + ok(nums(self.ans_of(0))[:1] == [12]))
        if t == "2" and self.ans_of(0):
            got = {w.strip().lower() for w in re.split(r"[,/;]+", self.ans_of(0)) if w.strip()}
            names = {"procyon": False, "denebola": True, "izar": True, "atria": True, "tarf": False}
            for n, good in names.items():
                if any(n in g for g in got):
                    out.append(n.capitalize() + ok(good))
                elif good:
                    out.append(n.capitalize() + T(" 빠짐", " missing"))
        if t == "3":
            s = self.ans_of(0)
            if s:
                out.append(s + ok(re.search(r"(α|alpha|alf|a)\s*\.?\s*hy(a|dr(ae|a))\b|alphard|알파르드", s, re.I) and not re.search(r"hyi|hydri", s, re.I)))
            m = minutes(self.ans_of(1)) if self.ans_of(1) else None
            if m is not None:
                d = abs(((m - 180) % 1440 + 2160) % 1440 - 720)
                out.append("3.1 %d:%02d (%d %s)" % (m // 60 % 24, m % 60, d, T("분 차이", "min off")) + ok(d <= 10, d <= 30))
            m = minutes(self.ans_of(2)) if self.ans_of(2) else None
            if m is not None:
                r = 4 if 900 <= m <= 930 else 3 if 900 <= m <= 960 else 2 if 900 <= m <= 990 else 1 if 870 <= m <= 990 else 0
                out.append("3.2 %d:%02d → %d%s" % (m // 60 % 24, m % 60, r, T("점", " pt")) + ok(r == 4, r > 0))
        if t == "T":
            lp = lamp_from(self.data["table"])
            out.append(T("책상 %d 기준값: 고도 %.2f°, 방위각 %.2f°", "Reference for table %d: altitude %.2f°, azimuth %.2f°") % (self.data["table"], lp["alt"], lp["az"]))
            for i, ref, mod, lab in ((0, lp["alt"], False, "h"), (1, lp["az"], True, "A")):
                n = nums(self.ans_of(i))
                if n:
                    d = abs(((n[0] - ref) % 360 + 540) % 360 - 180) if mod else abs(n[0] - ref)
                    out.append("%s %.2f° (%.2f° %s)%s" % (lab, n[0], d, T("차이", "off"), " ✓ 7.5" if d <= 1.5 else " △ 6.0" if d <= 2 else " ✗ 0"))
            out.append(T("지금 경통: 고도 %.2f°, 방위각 %.2f°", "Tube now: altitude %.2f°, azimuth %.2f°") % (self.tube["alt"], self.tube["az"]))
            n = nums(self.ans_of(2))
            if n:
                h = abs(n[0]) + (n[1] / 60 if len(n) > 1 else 0) + (n[2] / 3600 if len(n) > 2 else 0)
                out.append("α %dh%02dm" % (int(h), int(h % 1 * 60)) + ok(118 <= h * 60 < 119, 117 <= h * 60 < 120))
            n = nums(self.ans_of(3))
            if n:
                sg = -1 if self.ans_of(3).replace("−", "-").lstrip().startswith("-") else 1
                de = sg * (abs(n[0]) + (abs(n[1]) / 60 if len(n) > 1 else 0) + (abs(n[2]) / 3600 if len(n) > 2 else 0))
                out.append("δ %.2f°" % de + ok(-62 <= de <= -61))
            if self.ans_of(4):
                out.append(self.ans_of(4) + ok(re.search(r"(α|alpha|alf|a)\s*\.?\s*(hyi|hydri)\b|물뱀자리\s*(α|알파)", self.ans_of(4), re.I)))
            if self.ans_of(5):
                out.append(self.ans_of(5) + ok(re.fullmatch(r"\s*(hydrus|hyi|물뱀(자리)?)\s*", self.ans_of(5), re.I)))
        return ("\n\n" + T("내 답", "Your answers") + "\n" + "\n".join(out)) if out else ""

    def set_sheet(self, s):
        self.sheet = s
        self.undo = []
        for w in self.sbar.winfo_children():
            on = w.cget("text") == SHEETS[s]["name"]
            w.configure(bg="#f2c14e" if on else "#2b2f36", fg="#1c2027" if on else "#e8eef2")
        for w in self.form.winfo_children():
            w.destroy()
        if s == "scope":
            self.bar.pack_forget()
            r = tk.Frame(self.form, bg="#12161b")
            r.pack(fill="x", padx=6, pady=4)
            self.tlab = tk.Label(r, text="", bg="#12161b", fg="#f3d58a", font=("Segoe UI", 10, "bold"))
            self.tlab.pack(side="left")
            tk.Button(r, text=T("다른 책상에 앉기", "Sit at another table"), command=self.new_table, bg="#2b2f36", fg="#e8eef2", relief="flat").pack(side="left", padx=6)
            tk.Button(r, text=T("1단계 시작 (10분)", "Start stage 1 (10 min)"), command=self.start, bg="#2b2f36", fg="#e8eef2", relief="flat").pack(side="left", padx=6)
            self.tmr = tk.Label(r, text="", bg="#12161b", fg="#f3d58a", font=("Consolas", 10, "bold"))
            self.tmr.pack(side="left", padx=6)
            tk.Label(r, text=T("초점", "Focus"), bg="#12161b", fg="#9aa3ab").pack(side="left", padx=(12, 2))
            self.fvar = tk.DoubleVar(value=self.tube["foc"])
            tk.Scale(r, from_=-5, to=25, resolution=0.05, orient="horizontal", showvalue=False, length=260, variable=self.fvar, bg="#12161b", troughcolor="#2b2f36",
                     highlightthickness=0, command=lambda v: self.tube.__setitem__("foc", float(v))).pack(side="left")
            self.tlab.configure(text=T("책상 ", "Table ") + str(self.data["table"]))
        else:
            self.bar.pack(fill="x", pady=3, before=self.cv)
            tk.Label(self.form, text=T("시험지 그림입니다. 연필로 원, 선, 표시를 그리세요(○는 끌어서 반지름을 정합니다).", "The sheet's figure: draw circles, lines and marks in pencil (drag ○ to set the radius)."),
                     bg="#12161b", fg="#9aa3ab").pack(anchor="w", padx=6, pady=6)
        self.redraw()

    def new_table(self):
        n = self.data["table"]
        while n == self.data["table"]:
            n = random.randint(1, 40)
        self.data["table"] = n
        self.store()
        self.tube.update(az=0.0, alt=0.0, foc=17.0)
        self.fvar.set(17.0)
        self.tlab.configure(text=T("책상 ", "Table ") + str(n))

    def start(self):
        self.t0 = time.time()
        self.end = time.time() + 600
        self.tube.update(az=0.0, alt=0.0, foc=17.0)
        self.fvar.set(17.0)

    def set_tool(self, k):
        self.tool = k
        for kk, b in self.toolbtn.items():
            b.configure(bg="#f2c14e" if kk == k else "#2b2f36", fg="#1c2027" if kk == k else "#e8eef2")

    # ---- calculator
    def calc_run(self, e):
        src = e.get().strip()
        if not src:
            return
        try:
            v = self.calc.run(src)
            self.cres.configure(text=fmt(v))
            self.chist.configure(text=src + " =")
            e.delete(0, "end")
        except Exception:
            self.cres.configure(text=T("식 오류", "error"))

    def toggle_deg(self):
        self.calc.deg = not self.calc.deg
        self.degb.configure(text="DEG" if self.calc.deg else "RAD")

    # ---- the figures
    def geom(self):
        S = SHEETS[self.sheet]
        cw, ch = max(100, self.cv.winfo_width()), max(100, self.cv.winfo_height())
        k = min((cw - 16) / S["w"], (ch - 16) / S["h"])
        k = max([z for z in (2, 1.5, 1, 0.75, 2 / 3, 0.5, 1 / 3, 0.25) if z <= k] or [0.25])      # a few fixed steps keep the figure sharp
        return k, (cw - S["w"] * k) / 2, (ch - S["h"] * k) / 2

    def to_map(self, e):
        k, ox, oy = self.geom()
        return [(e.x - ox) / k, (e.y - oy) / k]

    def photo(self, name, k):
        key = (name, k)
        if key not in self.imgs:
            if name not in self.imgs:
                self.imgs[name] = tk.PhotoImage(data=IMG[name])
            src = self.imgs[name]
            a, b = {2: (2, 1), 1.5: (3, 2), 1: (1, 1), 0.75: (3, 4), 2 / 3: (2, 3), 0.5: (1, 2), 1 / 3: (1, 3), 0.25: (1, 4)}[k]
            self.imgs[key] = (src.zoom(a) if a > 1 else src).subsample(b) if b > 1 else (src.zoom(a) if a > 1 else src)
        return self.imgs[key]

    def redraw(self):
        cv = self.cv
        cv.delete("all")
        if self.sheet == "scope":
            self.draw_scope()
            return
        S = SHEETS[self.sheet]
        k, ox, oy = self.geom()
        X = lambda u: ox + u * k
        Y = lambda v: oy + v * k
        cv.create_rectangle(X(0), Y(0), X(S["w"]), Y(S["h"]), fill="#fff", outline="")
        cv.create_image(X(0), Y(0), image=self.photo(S["img"], k), anchor="nw")
        for it in self.marks() + ([self.drag["it"]] if self.drag else []):
            self.mark(it, X, Y, k)

    def mark(self, it, X, Y, k):
        cv = self.cv
        c = it.get("c", "#111")
        s = 11 * k
        t = it["t"]
        if "pts" in it:
            flat = [z for u, v in it["pts"] for z in (X(u), Y(v))]
            if len(flat) >= 4:
                cv.create_line(*flat, fill=c, width=max(1.2, s * 0.14), capstyle="round", joinstyle="round")
            return
        x, y = X(it["x"]), Y(it["y"])
        w = max(1.2, s * 0.14)
        if t == "circle":
            r = it.get("r", 10) * k
            cv.create_oval(x - r, y - r, x + r, y + r, outline=c, width=w)
        elif t == "dot":
            cv.create_oval(x - s * 0.3, y - s * 0.3, x + s * 0.3, y + s * 0.3, fill=c, outline=c)
        elif t == "cross":
            cv.create_line(x - s * 0.6, y - s * 0.6, x + s * 0.6, y + s * 0.6, fill=c, width=w)
            cv.create_line(x + s * 0.6, y - s * 0.6, x - s * 0.6, y + s * 0.6, fill=c, width=w)
        elif t == "plus":
            cv.create_line(x - s * 0.7, y, x + s * 0.7, y, fill=c, width=w)
            cv.create_line(x, y - s * 0.7, x, y + s * 0.7, fill=c, width=w)
        elif t == "text":
            cv.create_text(x, y, text=it["str"], fill=c, anchor="w", font=("Segoe UI", max(7, int(s * 1.1)), "bold"))

    # ---- the telescope
    def scope_geom(self):
        cw, ch = max(300, self.cv.winfo_width()), max(300, self.cv.winfo_height())
        strip = 110
        R = max(80, min((ch - strip - 30) / 2, cw * 0.28))
        return {"cw": cw, "ch": ch, "R": R, "cx": 16 + R, "cy": 12 + R, "sx": 2 * R + 40, "sw": cw - 2 * R - 56, "st": ch - strip, "sh": strip - 10}

    def basis(self):
        a, h = self.tube["az"] * DEG, self.tube["alt"] * DEG
        f = [math.sin(a) * math.cos(h), math.cos(a) * math.cos(h), math.sin(h)]
        r = [math.cos(a), -math.sin(a), 0]
        return f, r, [r[1] * f[2] - r[2] * f[1], r[2] * f[0] - r[0] * f[2], r[0] * f[1] - r[1] * f[0]]

    def blur(self, d):
        return GS_D * abs(self.tube["foc"] - focus_of(d)) / 1000 / (GS_F * GS_F)

    def draw_scope(self):
        cv, G = self.cv, self.scope_geom()
        R, cx, cy = G["R"], G["cx"], G["cy"]
        cv.configure(bg="#1a1d22")
        s = R / math.tan(GS_FOV / 2 * DEG)
        f, r, u = self.basis()

        def P(x):
            Z = dot(x, f)
            if Z <= 0:
                return None
            return cx - dot(x, r) / Z * s, cy + dot(x, u) / Z * s
        glow = max(0.0, 1 - self.tube["alt"] / 20)
        cv.create_oval(cx - R - 3, cy - R - 3, cx + R + 3, cy + R + 3, fill="#000", outline="#000")
        cv.create_oval(cx - R, cy - R, cx + R, cy + R, fill=hexc(10 + 16 * glow, 11 + 13 * glow, 18 + 12 * glow), outline="")
        J = self.J()
        HM = hor_matrix(J)
        cEq = mvT(HM, f)
        cl = math.cos((GS_FOV / 2 + 1) * DEG)
        bs = self.blur(float("inf")) * s / 2 + 0.7
        for v, m, bv in STARS:
            if dot(v, cEq) < cl:
                continue
            alt, az = altaz(mv(HM, v))
            alt += refr(alt)
            if alt < skyline(az):
                continue
            p = P(hvec(alt, az))
            if not p or (p[0] - cx) ** 2 + (p[1] - cy) ** 2 > R * R:
                continue
            d = GS_LIM - (m + 0.25 * airmass(alt)) - 1.5 * glow
            if d <= 0:
                continue
            k = min(1, 0.25 + 0.1 * d) * min(1, (1.6 / bs) ** 2)
            cr, cg, cb = bv_rgb(bv)
            rad = max(0.9, bs * min(1, 0.6 + 0.05 * d))
            cv.create_oval(p[0] - rad, p[1] - rad, p[0] + rad, p[1] + rad, fill=hexc(255 * cr * k, 255 * cg * k, 255 * cb * k), outline="")
        # the ground: the skyline across the field, filled towards the bottom of the world (the top of the inverted image)
        if self.tube["alt"] - GS_FOV < 7:
            span = GS_FOV / max(0.2, math.cos(self.tube["alt"] * DEG)) + 0.5
            line = []
            for i in range(61):
                az = self.tube["az"] - span + 2 * span * i / 60
                p, q = P(hvec(skyline(az), az)), P(hvec(skyline(az) - 6, az))
                if p and q:
                    line.append((p, q))
            if len(line) > 1:
                poly = [c for p, q in line for c in p] + [c for p, q in reversed(line) for c in q]
                cv.create_polygon(*poly, fill="#030305", outline="")
        lp = lamp_from(self.data["table"])
        bl = self.blur(lp["dist"]) * s / 2
        tp, bt = P(hvec(lp["alt"], lp["az"])), P(hvec(max(lp["ground"], skyline(lp["az"]) - 2), lp["az"]))
        if tp and bt:
            mw = MAST_W / lp["dist"] * s
            a = min(1, mw / (mw + bl))
            mc = hexc(4 + (10 + 16 * glow) * (1 - a), 4 + (11 + 13 * glow) * (1 - a), 6 + (18 + 12 * glow) * (1 - a))
            cv.create_line(tp[0], tp[1] - 0.05 / lp["dist"] * s, bt[0], bt[1], fill=mc, width=mw + bl)
            # the bulb: a 4 cm red disc, its edge spread by the blur, with a little glare round it
            rb = max(1.5, BULB / lp["dist"] * s)
            ro = rb + bl
            k = min(1, (rb / ro) ** 2)
            for q, a2 in ((ro * 2.0 + 3, 0.12 + 0.2 * k), (ro, 0.3 + 0.55 * k), (max(1.0, rb - bl), 0.45 + 0.55 * k)):
                cv.create_oval(tp[0] - q, tp[1] - q, tp[0] + q, tp[1] + q, fill=hexc(255 * a2 + 10, 70 * a2 + 8, 50 * a2 + 10), outline="")
        # mask the outside of the field
        w = R * 0.5
        cv.create_oval(cx - R - w / 2, cy - R - w / 2, cx + R + w / 2, cy + R + w / 2, outline="#000", width=w)
        x1, y1, x2, y2 = cx - R - 8, cy - R - 8, cx + R + 8, cy + R + 8
        for box in ((0, 0, G["cw"], y1), (0, y2, G["cw"], G["st"] - 4), (0, y1, x1, y2), (x2, y1, G["cw"], y2)):
            cv.create_rectangle(*box, fill="#1a1d22", outline="")
        cv.create_text(cx - R + 6, cy - R + 4, text=T("접안렌즈 20 mm (25×)", "Eyepiece 20 mm (25×)"), anchor="nw", fill="#9aa3ab", font=("Segoe UI", 9, "bold"))
        self.draw_scale(G["sx"], 34, G["sw"], 64, self.tube["az"], True, T("방위각 눈금 (북 = 0°, 동쪽으로 증가)", "Azimuth scale (N = 0°, eastward)"), -1e9, 1e9)
        self.draw_scale(G["sx"], 150, G["sw"], 64, self.tube["alt"], False, T("고도 눈금 (각도기)", "Altitude scale (protractor)"), -10, 90)
        self.draw_strip(G)

    def draw_scale(self, x0, y0, w, h, val, mod, lab, lo, hi):
        cv, PXD = self.cv, 12
        c = x0 + w / 2
        cv.create_rectangle(x0, y0, x0 + w, y0 + h, fill="#c9c5b8", outline="#555")
        span = int(w / 2 / PXD) + 1
        for k in range(int(math.floor(val)) - span, int(math.ceil(val)) + span + 1):
            if k < lo or k > hi:
                continue
            x = c + (k - val) * PXD
            if x < x0 + 1 or x > x0 + w - 1:
                continue
            kk = k % 360 if mod else k
            L = 24 if kk % 10 == 0 else 16 if kk % 5 == 0 else 10
            cv.create_line(x, y0 + h, x, y0 + h - L, fill="#1b1b1b", width=1.6 if kk % 10 == 0 else 1)
            if kk % 10 == 0:
                cv.create_text(x, y0 + h - 30, text=str(kk), fill="#1b1b1b", font=("Arial", 9, "bold"))
            elif kk % 5 == 0:
                cv.create_text(x, y0 + h - 23, text=str(kk), fill="#1b1b1b", font=("Arial", 8))
        cv.create_line(c, y0 - 6, c, y0 + h, fill="#d22", width=1.6)
        cv.create_polygon(c - 6, y0 - 8, c + 6, y0 - 8, c, y0 - 1, fill="#d22", outline="")
        cv.create_text(x0, y0 - 12, text=lab, anchor="sw", fill="#c3cbd2", font=("Segoe UI", 9, "bold"))

    def draw_strip(self, G):
        """A naked-eye look all round the horizon: azimuth 0-360 across, altitude -5 to 40 up."""
        cv = self.cv
        x0, y0, w, h = 10, G["st"], G["cw"] - 20, G["sh"]
        X = lambda az: x0 + norm360(az) / 360 * w
        Y = lambda alt: y0 + h - (alt + 5) / 45 * h
        cv.create_rectangle(x0, y0, x0 + w, y0 + h, fill="#0b0d14", outline="#333")
        HM = hor_matrix(self.J())
        for v, m, bv in STARS:
            if m > 3.6:
                continue
            alt, az = altaz(mv(HM, v))
            if alt < skyline(az) or alt > 40:
                continue
            q = max(0.6, 2.6 - 0.5 * m)
            cv.create_oval(X(az) - q, Y(alt) - q, X(az) + q, Y(alt) + q, fill="#e8eef2", outline="")
        pts = []
        for i in range(0, 361, 2):
            pts += [X(i) if i < 360 else x0 + w, Y(skyline(i))]
        cv.create_polygon(x0, y0 + h, *pts, x0 + w, y0 + h, fill="#050506", outline="#22252b")
        for i, n in enumerate("NESW"):
            cv.create_text(X(i * 90) + (8 if i == 0 else 0), y0 + h - 8, text=T("북동남서", "NESW")[i], fill="#9aa3ab", font=("Segoe UI", 9, "bold"))
        lp = lamp_from(self.data["table"])
        cv.create_line(X(lp["az"]), Y(lp["alt"]), X(lp["az"]), Y(skyline(lp["az"])), fill="#111")
        cv.create_oval(X(lp["az"]) - 3, Y(lp["alt"]) - 3, X(lp["az"]) + 3, Y(lp["alt"]) + 3, fill="#ff3b30", outline="")
        tx, ty = X(self.tube["az"]), Y(self.tube["alt"])
        cv.create_oval(tx - 7, ty - 7, tx + 7, ty + 7, outline="#ffffff")
        cv.create_text(tx + 10, ty + 10, text=T("망원경", "telescope"), anchor="nw", fill="#cfd5da", font=("Segoe UI", 8))
        cv.create_text(x0 + 6, y0 + 4, text=T("맨눈으로 본 지평선 (클릭: 눈으로 겨누기)", "The horizon by eye (click: aim by eye)"), anchor="nw", fill="#9aa3ab", font=("Segoe UI", 8))

    def nudge(self, dx, dy):
        G = self.scope_geom()
        s = G["R"] / math.tan(GS_FOV / 2 * DEG)
        self.tube["az"] = norm360(self.tube["az"] - dx / s / DEG / max(0.05, math.cos(self.tube["alt"] * DEG)))
        self.tube["alt"] = max(-10, min(89.5, self.tube["alt"] - dy / s / DEG))

    def key_nudge(self, e, d):
        if self.sheet == "scope" and not isinstance(e.widget, tk.Entry):
            self.nudge(*d)
            self.redraw()

    def wheel(self, d):
        if self.sheet == "scope":
            self.tube["foc"] = max(-5, min(25, self.tube["foc"] + 0.25 * d))
            self.fvar.set(self.tube["foc"])
            self.redraw()

    # ---- the pencil, and the telescope's handles
    def push(self):
        self.undo.append(json.dumps(self.marks()))

    def down(self, e):
        if self.sheet == "scope":
            G = self.scope_geom()
            if (e.x - G["cx"]) ** 2 + (e.y - G["cy"]) ** 2 <= G["R"] ** 2:
                self.sdrag = {"k": "ep", "x": e.x, "y": e.y}
            elif e.x >= G["sx"] and e.y < G["st"] - 10:
                self.sdrag = {"k": "az" if e.y < 120 else "alt", "x": e.x, "y": e.y}
            elif e.y >= G["st"]:
                az = (e.x - 10) / (G["cw"] - 20) * 360
                alt = (G["st"] + G["sh"] - e.y) / G["sh"] * 45 - 5
                g = lambda: (random.random() + random.random() + random.random() - 1.5) * 1.2
                self.tube["alt"] = max(-5, min(88, alt + g()))
                self.tube["az"] = norm360(az + g() / max(0.2, math.cos(alt * DEG)))
                self.redraw()
            return
        p = self.to_map(e)
        if self.tool == "erase":
            best, bi = 1e9, -1
            for i, it in enumerate(self.marks()):
                d = min(math.hypot(p[0] - u, p[1] - v) for u, v in it["pts"]) if "pts" in it else math.hypot(p[0] - it["x"], p[1] - it["y"])
                if d < best:
                    best, bi = d, i
            if bi >= 0 and best < 18:
                self.push()
                del self.marks()[bi]
                self.store()
                self.redraw()
            return
        if self.tool == "text":
            w = tk.Toplevel(self.root)
            v = tk.StringVar()
            en = tk.Entry(w, textvariable=v, font=("Segoe UI", 12))
            en.pack(padx=10, pady=10)
            en.focus_set()

            def ok(_=None):
                s = v.get().strip()
                w.destroy()
                if s:
                    self.push()
                    self.marks().append({"t": "text", "x": p[0], "y": p[1], "str": s, "c": self.col})
                    self.store()
                    self.redraw()
            en.bind("<Return>", ok)
            return
        if self.tool in ("pen", "line"):
            self.drag = {"it": {"t": self.tool, "pts": [p, list(p)], "c": self.col}}
            return
        if self.tool == "circle":
            self.drag = {"it": {"t": "circle", "x": p[0], "y": p[1], "r": 10, "c": self.col}, "circle": True}
            return
        self.push()
        self.marks().append({"t": self.tool, "x": p[0], "y": p[1], "c": self.col})
        self.store()
        self.redraw()

    def move(self, e):
        if self.sheet == "scope":
            if not self.sdrag:
                return
            dx, dy = e.x - self.sdrag["x"], e.y - self.sdrag["y"]
            self.sdrag.update(x=e.x, y=e.y)
            if self.sdrag["k"] == "ep":
                self.nudge(-dx, -dy)
            elif self.sdrag["k"] == "az":
                self.tube["az"] = norm360(self.tube["az"] - dx / 12)
            else:
                self.tube["alt"] = max(-10, min(89.5, self.tube["alt"] - dx / 12))
            self.redraw()
            return
        if not self.drag:
            return
        p = self.to_map(e)
        it = self.drag["it"]
        if self.drag.get("circle"):
            it["r"] = max(4, math.hypot(p[0] - it["x"], p[1] - it["y"]))
        elif it["t"] == "line":
            it["pts"][1] = p
        else:
            it["pts"].append(p)
        self.redraw()

    def up(self, e):
        if self.sheet == "scope":
            self.sdrag = None
            return
        if not self.drag:
            return
        it = self.drag["it"]
        self.drag = None
        self.push()
        self.marks().append(it)
        self.store()
        self.redraw()

    def do_undo(self):
        if self.undo and self.sheet != "scope":
            self.data["marks"][self.sheet] = json.loads(self.undo.pop())
            self.store()
            self.redraw()

    def clear(self):
        if self.sheet != "scope" and self.marks() and messagebox.askyesno("IOAA 2024", T("이 종이에 그린 것을 모두 지울까요?", "Erase everything drawn on this sheet?")):
            self.push()
            self.data["marks"][self.sheet] = []
            self.store()
            self.redraw()


if __name__ == "__main__":
    root = tk.Tk()
    App(root)
    root.mainloop()
